import{_ as o,o as s,c as a,a as e}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"写作课作业-048","description":"","frontmatter":{"date":"2020-09-06T20:11:45","title":"写作课作业-048","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/048.md","filePath":"posts/homework/048.md"}'),l={name:"posts/homework/048.md"};function r(n,t,p,c,d,i){return s(),a("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"9.5写作作业：结合学习、工作和生活谈谈“有效沟通”的重要性，最好有具体例子，至少运用一个转折、递进和类比。")],-1),e("p",null,"沟通简单来说是人与人之间，通过语言，动作，文字等方式传递信息和得到反馈，以达到特定目标的行为过程。如果达成了特定目的则认为是有效沟通，否则是沟通出现了偏差，甚至是沟通失败。但沟通双方的状态，知识和经验结构，准备的充分性，环境的噪音、氛围等因素都会影响沟通的效果，有效沟通常常无法达成。",-1),e("p",null,"工作一段时间后，老大让我开始带实习生，一开始讲解任务，之后会问听懂了么？得到的答案是是的。回头做出来的东西和自己交代的不太一样。和老大反馈后，他说你可以让他复述下，看看如何，如何说不清楚，那就多讲一遍。试了几次这种方法效果还可以，而后自己带小组长也是这么教他们的。",-1),e("p",null,"公司会请些人来做技术培训，有时演讲者爱用缩写，但又没有给出解释，自认为高大上，但听的人能却是云里雾里的。有时自己也碍于情面，不好发问，最后收效甚微。",-1),e("p",null,"我们之前了解到叙述谬误，对于同一件事情，不同的描述，通常会有不一样的反应。对于自己的亲人来说，经常会出现“亲相贱”的情况，有时说话不注意措辞或分寸，最终却因为对方情绪或者状态的问题闹得不开心。",-1)])])}const _=o(l,[["render",r]]);export{u as __pageData,_ as default};
